"""CPU map backend and the complete control-plane agent.

``MemoryMap`` holds the immutable transition cells of every resident image and
``Agent`` implements the versioned lifecycle: atomic publication and retirement
of images, pinned epochs, multiplexed requests per process identity, cloned
identities, transport handoffs through connections and storage handoffs through
inodes, plus the exact resource census reported by ``inspect``.

Every operation is all-or-nothing: preconditions and capacities are checked
before the first mutation, so a rejection cannot move a high-water mark, a
reference count or a cell total.
"""
import os
import struct
import sys

_PKG_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if _PKG_DIR not in sys.path:
    sys.path.insert(0, _PKG_DIR)

from ebpf.create_dfa import create  # noqa: E402
from syntax import PolicyError  # noqa: E402

__all__ = ['Agent', 'MemoryMap', 'DENY', 'Rejected']

DENY = 4294967295
U32 = 4294967295
MAGIC = b'EMC4'
_WIRE = struct.Struct('>4sIIIII')
MAX_ROWS = 8192

_OK = '{"ok":true}'
_REJECTED = '{"error":"rejected"}'


class Rejected(Exception):
    """A replay precondition or capacity failure; nothing changed."""


def _pack(epoch, state, label, stream, generation):
    return _WIRE.pack(MAGIC, epoch, state, label, stream, generation).hex()


class MemoryMap:
    """Immutable per-image transition cells with an exact census."""

    def __init__(self):
        self.blocks = {}
        self.cells = 0

    def install(self, epoch, rows, cells):
        self.blocks[epoch] = rows
        self.cells += cells

    def remove(self, epoch, cells):
        del self.blocks[epoch]
        self.cells -= cells

    def get(self, epoch):
        return self.blocks.get(epoch)


class Image:
    __slots__ = ('epoch', 'accept', 'rows', 'cells', 'refs')

    def __init__(self, epoch, accept, rows, cells):
        self.epoch = epoch
        self.accept = accept
        self.rows = rows
        self.cells = cells
        self.refs = 0


class Unit:
    __slots__ = ('key', 'service', 'generation', 'label', 'mark', 'contexts')

    def __init__(self, key, service, generation, label):
        self.key = key
        self.service = service
        self.generation = generation
        self.label = label
        self.mark = 0
        self.contexts = {}


class Connection:
    __slots__ = ('identifier', 'generation', 'mark', 'packets')

    def __init__(self, identifier, generation):
        self.identifier = identifier
        self.generation = generation
        self.mark = 0
        self.packets = {}


class Packet:
    __slots__ = ('epoch', 'state', 'destination', 'label', 'wire', 'receipt')

    def __init__(self, epoch, state, destination, label, wire):
        self.epoch = epoch
        self.state = state
        self.destination = destination
        self.label = label
        self.wire = wire
        self.receipt = None


class Agent:
    """One job's control plane: registries, limits and all live objects."""

    def __init__(self, services, limits):
        self.services = list(services)
        self.limits = dict(limits)
        ordered = sorted(services, key=lambda service: service['label'])
        self.columns = [service['label'] for service in ordered]
        self.column_of = {service['name']: position
                          for position, service in enumerate(ordered)}
        self.label_of = {service['name']: service['label'] for service in services}
        self.B = {'access_control': MemoryMap()}
        self.images = {}
        self.active = None
        self.stage_mark = 0
        self.units = {}
        self.spawn_mark = {}
        self.connections = {}
        self.connection_mark = {}
        self.files = {}
        self.file_mark = {}
        self.context_count = 0
        self.packet_count = 0

    # ------------------------------------------------------------------ helpers

    def _map(self):
        return self.B['access_control']

    def _image(self, epoch):
        image = self.images.get(epoch)
        if image is None:
            # Cannot happen while a reference exists; refuse rather than guess.
            raise Rejected('epoch %r is not resident' % (epoch,))
        return image

    def _advance(self, epoch, state, column):
        if state == DENY:
            return DENY
        image = self._image(epoch)
        if column < 0 or column >= len(image.columns if False else self.columns):
            raise Rejected('column')
        return image.rows[state][column]

    def _unit(self, identity):
        unit = self.units.get((identity[0], identity[1]))
        if unit is None or unit.generation != identity[2]:
            raise Rejected('unit')
        return unit

    def _context(self, unit, rid):
        context = unit.contexts.get(rid)
        if context is None:
            raise Rejected('context')
        return context

    def _room_units(self):
        if len(self.units) + 1 > self.limits['units']:
            raise Rejected('units')

    def _room_contexts(self, extra):
        if self.context_count + extra > self.limits['contexts']:
            raise Rejected('contexts')

    def _room_packets(self):
        if self.packet_count + 1 > self.limits['packets']:
            raise Rejected('packets')

    def _room_connections(self):
        if len(self.connections) + 1 > self.limits['connections']:
            raise Rejected('connections')

    def _room_files(self):
        if len(self.files) + 1 > self.limits['files']:
            raise Rejected('files')

    def _reserve_unit_identity(self, identity):
        key = (identity[0], identity[1])
        if key in self.units:
            raise Rejected('unit in use')
        if identity[2] <= self.spawn_mark.get(key, 0):
            raise Rejected('generation')
        return key

    # -------------------------------------------------------------- operations

    def _stage(self, epoch, policy):
        if epoch <= self.stage_mark:
            raise Rejected('epoch')
        if len(self.images) + 1 > self.limits['images']:
            raise Rejected('images')
        compiled = create(policy, self.services)
        rows = compiled['rows']
        if len(rows) > MAX_ROWS:
            raise Rejected('rows')
        cells = compiled['cells']
        if self._map().cells + cells > self.limits['cells']:
            raise Rejected('cells')
        self.images[epoch] = Image(epoch, tuple(compiled['accept']),
                                   tuple(tuple(row) for row in rows), cells)
        self._map().install(epoch, self.images[epoch].rows, cells)
        self.stage_mark = epoch
        return _encode_stage(epoch, self.images[epoch])

    def _commit(self, epoch):
        if epoch not in self.images:
            raise Rejected('epoch')
        self.active = epoch
        return _OK

    def _retire(self, epoch):
        image = self.images.get(epoch)
        if image is None or epoch == self.active or image.refs:
            raise Rejected('retire')
        del self.images[epoch]
        self._map().remove(epoch, image.cells)
        return _OK

    def _spawn(self, identity, service):
        column = self.column_of.get(service)
        if column is None:
            raise Rejected('unregistered service')
        key = self._reserve_unit_identity(identity)
        self._room_units()
        self.units[key] = Unit(key, service, identity[2], self.label_of[service])
        self.spawn_mark[key] = identity[2]
        return _OK

    def _clone(self, parent, child):
        source = self._unit(parent)
        key = self._reserve_unit_identity(child)
        self._room_units()
        copies = source.contexts
        self._room_contexts(len(copies))
        copy = {}
        for rid, context in copies.items():
            copy[rid] = (context[0], context[1])
            self._image(context[0]).refs += 1
        self.units[key] = _cloned_unit(key, source, child[2], copy)
        self.spawn_mark[key] = child[2]
        self.context_count += len(copies)
        return _OK

    def _exit(self, identity):
        unit = self._unit(identity)
        del self.units[unit.key]
        for epoch, _state in unit.contexts.values():
            self._image(epoch).refs -= 1
        self.context_count -= len(unit.contexts)
        return _OK

    def _begin(self, identity, rid):
        if self.active is None:
            raise Rejected('no active image')
        unit = self._unit(identity)
        if rid <= unit.mark:
            raise Rejected('request mark')
        self._room_contexts(1)
        image = self._image(self.active)
        state = image.rows[0][self.column_of[unit.service]]
        unit.contexts[rid] = (self.active, state)
        unit.mark = rid
        image.refs += 1
        self.context_count += 1
        return '{"ok":true,"epoch":%d,"state":%d}' % (self.active, state)

    def _finish(self, identity, rid):
        unit = self._unit(identity)
        context = self._context(unit, rid)
        del unit.contexts[rid]
        image = self._image(context[0])
        image.refs -= 1
        self.context_count -= 1
        allow = False if context[1] == DENY else bool(image.accept[context[1]])
        return '{"ok":true,"allow":%s}' % ('true' if allow else 'false')

    def _open(self, connection):
        identifier = connection[0]
        if identifier in self.connections:
            raise Rejected('already open')
        if connection[1] <= self.connection_mark.get(identifier, 0):
            raise Rejected('generation')
        self._room_connections()
        self.connections[identifier] = Connection(identifier, connection[1])
        self.connection_mark[identifier] = connection[1]
        return _OK

    def _close(self, connection):
        opened = self.connections.get(connection[0])
        if opened is None or opened.generation != connection[1]:
            raise Rejected('connection')
        del self.connections[connection[0]]
        for packet in opened.packets.values():
            self._image(packet.epoch).refs -= 1
        self.packet_count -= len(opened.packets)
        return _OK

    def _send(self, identity, rid, connection, stream, destination):
        label = self.label_of.get(destination)
        if label is None:
            raise Rejected('unregistered destination')
        unit = self._unit(identity)
        context = self._context(unit, rid)
        opened = self.connections.get(connection[0])
        if opened is None or opened.generation != connection[1]:
            raise Rejected('connection')
        if stream <= opened.mark:
            raise Rejected('stream mark')
        self._room_packets()
        wire = _pack(context[0], context[1], label, stream, opened.generation)
        opened.packets[stream] = Packet(context[0], context[1], destination, label, wire)
        opened.mark = stream
        self._image(context[0]).refs += 1
        self.packet_count += 1
        return '{"ok":true,"wire":"%s"}' % wire

    def _recv(self, connection, stream, identity, rid, wire):
        opened = self.connections.get(connection[0])
        if opened is None or opened.generation != connection[1]:
            raise Rejected('connection')
        packet = opened.packets.get(stream)
        if packet is None:
            raise Rejected('packet')
        unit = self._unit(identity)
        if unit.service != packet.destination:
            raise Rejected('destination')
        if wire is not None and (len(wire) != 48 or wire.lower() != packet.wire):
            raise Rejected('wire')
        receipt = packet.receipt
        if receipt is not None:
            held, recorded, epoch, state = receipt
            if held != identity or recorded != rid:
                raise Rejected('duplicate')
            if identity not in self.units or rid not in self.units[identity].contexts:
                raise Rejected('duplicate')
            return '{"ok":true,"epoch":%d,"state":%d}' % (epoch, state)
        if rid <= unit.mark:
            raise Rejected('request mark')
        self._room_contexts(1)
        epoch = packet.epoch
        state = self._advance(epoch, packet.state, self.column_of[unit.service])
        unit.contexts[rid] = (epoch, state)
        unit.mark = rid
        self._image(epoch).refs += 1
        self.context_count += 1
        packet.receipt = ((unit.key[0], unit.key[1], unit.key[2]), rid, epoch, state)
        return '{"ok":true,"epoch":%d,"state":%d}' % (epoch, state)

    def _store(self, identity, rid, file):
        unit = self._unit(identity)
        context = self._context(unit, rid)
        identifier = file[0]
        current = self.files.get(identifier)
        if current is None:
            if file[1] <= self.file_mark.get(identifier, 0):
                raise Rejected('generation')
            self._room_files()
        elif current[0] != file[1]:
            raise Rejected('generation')
        self.files[identifier] = (file[1], context[0], context[1])
        self.file_mark[identifier] = max(self.file_mark.get(identifier, 0), file[1])
        self._image(context[0]).refs += 1
        if current is not None:
            self._image(current[1]).refs -= 1
        return _OK

    def _load(self, file, identity, rid):
        current = self.files.get(file[0])
        if current is None or current[0] != file[1]:
            raise Rejected('file')
        unit = self._unit(identity)
        if rid <= unit.mark:
            raise Rejected('request mark')
        self._room_contexts(1)
        epoch = current[1]
        state = self._advance(epoch, current[2], self.column_of[unit.service])
        unit.contexts[rid] = (epoch, state)
        unit.mark = rid
        self._image(epoch).refs += 1
        self.context_count += 1
        return '{"ok":true,"epoch":%d,"state":%d}' % (epoch, state)

    def _unlink(self, file):
        current = self.files.get(file[0])
        if current is None or current[0] != file[1]:
            raise Rejected('file')
        del self.files[file[0]]
        self._image(current[1]).refs -= 1
        return _OK

    def _inspect(self):
        parts = ['{"ok":true,"active":']
        parts.append('null' if self.active is None else str(self.active))
        parts.append(',"images":[')
        first = True
        for epoch in sorted(self.images):
            image = self.images[epoch]
            if not first:
                parts.append(',')
            first = False
            parts.append('[%d,%d,%d,%d]' % (epoch, len(image.rows), image.cells, image.refs))
        parts.append('],"units":%d,"contexts":%d,"connections":%d,"packets":%d,"files":%d}'
                     % (len(self.units), self.context_count, len(self.connections),
                        self.packet_count, len(self.files)))
        return ''.join(parts)

    # ------------------------------------------------------------- dispatch

    _HANDLERS = {
        'stage': lambda self, e: self._stage(e['epoch'], e['policy']),
        'commit': lambda self, e: self._commit(e['epoch']),
        'retire': lambda self, e: self._retire(e['epoch']),
        'spawn': lambda self, e: self._spawn(e['unit'], e['service']),
        'clone': lambda self, e: self._clone(e['parent'], e['child']),
        'exit': lambda self, e: self._exit(e['unit']),
        'begin': lambda self, e: self._begin(e['unit'], e['rid']),
        'finish': lambda self, e: self._finish(e['unit'], e['rid']),
        'open': lambda self, e: self._open(e['connection']),
        'close': lambda self, e: self._close(e['connection']),
        'send': lambda self, e: self._send(e['unit'], e['rid'], e['connection'],
                                           e['stream'], e['destination']),
        'recv': lambda self, e: self._recv(e['connection'], e['stream'], e['unit'],
                                           e['rid'], e['wire']),
        'store': lambda self, e: self._store(e['unit'], e['rid'], e['file']),
        'load': lambda self, e: self._load(e['file'], e['unit'], e['rid']),
        'unlink': lambda self, e: self._unlink(e['file']),
        'inspect': lambda self, e: self._inspect(),
    }

    def event_text(self, event):
        """Replay one event and return its JSON outcome text."""
        handler = self._HANDLERS.get(event['op'])
        if handler is None:
            return _REJECTED
        try:
            return handler(self, event)
        except Exception:
            return _REJECTED

    def event(self, event):
        """Replay one event and return its outcome as a Python object."""
        import json
        return json.loads(self.event_text(event))

    def census(self):
        """Independent recomputation of the resource census, for self checks."""
        contexts = 0
        references = {}
        for unit in self.units.values():
            contexts += len(unit.contexts)
            for epoch, _state in unit.contexts.values():
                references[epoch] = references.get(epoch, 0) + 1
        packets = 0
        for connection in self.connections.values():
            packets += len(connection.packets)
            for packet in connection.packets.values():
                references[packet.epoch] = references.get(packet.epoch, 0) + 1
        for epoch, _state in self.files.values()[0:] if False else list(self.files.values()):
            references[epoch] = references.get(epoch, 0) + 1
        return {'contexts': contexts, 'packets': packets,
                'cells': self._map().cells, 'references': references}


def _cloned_unit(key, source, generation, contexts):
    unit = Unit(key, source.service, generation, source.label)
    unit.mark = source.mark
    unit.contexts = contexts
    return unit


def _encode_stage(epoch, image):
    accept = ','.join('true' if flag else 'false' for flag in image.accept)
    rows = ','.join('[%s]' % ','.join(str(cell) for cell in row) for row in image.rows)
    return '{"ok":true,"epoch":%d,"image":{"accept":[%s],"rows":[%s]}}' % (epoch, accept, rows)
